def get_translation(word, phrase):
    """取翻译, 优先从 ZH 字典, 否则返回空串"""
    if word in ZH and phrase in ZH[word]:
        return ZH[word][phrase]
    if word in EXTRA_ZH and phrase in EXTRA_ZH[word]:
        return EXTRA_ZH[word][phrase]
    return ''

with open('public/data/words.json') as f:
    data = json.load(f)

words = data['words'] if isinstance(data, dict) and 'words' in data else data

filled = 0
updated = 0
for w in words:
    if not isinstance(w, dict):
        continue
    word = w.get('word', '')
    phrases = w.get('phrases', [])
    if not phrases and word in PHRASES:
        # 新填: 转 dict {phrase, translation} 格式
        new_phrases = []
        for p in PHRASES[word]:
            if isinstance(p, str):
                new_phrases.append({'phrase': p, 'translation': get_translation(word, p)})
            elif isinstance(p, dict):
                new_phrases.append(p)
        w['phrases'] = new_phrases
        filled += 1
    elif phrases and (word in ZH or word in EXTRA_ZH):
        # 已存在, 补翻译 (针对 W92 补的 {phrase, translation: ''} 格式)
        new_phrases = []
        for p in phrases:
            if isinstance(p, dict) and p.get('phrase') and not p.get('translation', '').strip():
                # 空翻译, 补
                p['translation'] = get_translation(word, p['phrase'])
                updated += 1
            new_phrases.append(p)
        w['phrases'] = new_phrases

print(f'W92 补短语: {filled} 词')
print(f'W92 补翻译: {updated} 条')

with open('public/data/words.json', 'w') as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

# 验证
with open('public/data/words.json') as f:
    data2 = json.load(f)
words2 = data2['words'] if isinstance(data2, dict) and 'words' in data2 else data2
missing2 = sum(1 for w in words2 if isinstance(w, dict) and not w.get('phrases'))
total = len(words2)
print(f'剩余缺短语: {missing2} / {total} = {missing2/total*100:.1f}%')

no_5_9 = sum(1 for w in words2 if isinstance(w, dict) and not w.get('phrases') and 5 <= len(w.get('word','')) <= 9)
print(f'5-9 字符缺短语: {no_5_9}')

# 验证 W92 翻译完整
empty_zh = 0
for w in words2:
    if w.get('phrases') and 5 <= len(w.get('word','')) <= 9 and (w['word'] in ZH or w['word'] in EXTRA_ZH):
        for p in w['phrases']:
            if isinstance(p, dict) and 'phrase' in p and not p.get('translation', '').strip():
                empty_zh += 1
print(f'W92 翻译残留空: {empty_zh}')
